function initThemeToggle(){const e=document.querySelector("#theme-toggle");e&&(e.addEventListener("click",()=>{document.body.classList.toggle("dark-mode"),localStorage.setItem("dokra-theme",document.body.classList.contains("dark-mode")?"dark":"light")}),"dark"===localStorage.getItem("dokra-theme")&&document.body.classList.add("dark-mode"))}function renderStats(e,n){const t=document.getElementById(n);t&&(t.innerHTML=e.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon" aria-hidden="true">${e.icon}</span>\n            <div>\n                <h4>${e.label}</h4>\n                <p>${e.value}</p>\n            </div>\n        </div>\n    `).join(""))}function renderHistory(e,n){const t=document.getElementById(n);t&&(t.innerHTML=e.map(e=>`\n        <div class="history-entry">\n            <div class="history-period">${e.period}</div>\n            <h4>${e.title}</h4>\n            <p>${e.description}</p>\n        </div>\n    `).join(""))}function renderProcess(e,n){const t=document.getElementById(n);t&&(t.innerHTML=e.map(e=>`\n        <div class="process-step">\n            <div class="step-number">${String(e.step).padStart(2,"0")}</div>\n            <div class="step-content">\n                <h4>${e.title}</h4>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderCommunities(e,n){const t=document.getElementById(n);t&&(t.innerHTML=e.map(e=>`\n        <div class="community-card">\n            <h4>${e.name}</h4>\n            <p>${e.description}</p>\n        </div>\n    `).join(""))}function renderGallery(e,n){const t=document.getElementById(n);t&&(t.innerHTML=e.map(e=>`\n        <figure class="gallery-item">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" onerror="this.closest('.gallery-item').style.display='none';">\n            <figcaption>${e.caption}</figcaption>\n        </figure>\n    `).join(""))}function renderReferences(e,n){const t=document.getElementById(n);t&&(t.innerHTML=e.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">${e.text}</a>\n        </li>\n    `).join(""))}document.addEventListener("DOMContentLoaded",()=>{initThemeToggle(),renderStats(DOKRA_INFO.quickStats,"quick-stats"),renderHistory(HISTORY_CHAPTERS,"history-timeline"),renderProcess(LOST_WAX_PROCESS,"process-steps"),renderCommunities(ARTISAN_COMMUNITIES,"communities-grid"),renderGallery(GALLERY_IMAGES,"gallery-grid"),renderReferences(REFERENCES,"references")});